TEST_F(PmEditorFindLineTest, FindLine0SingleLine) {
    SetBuffer("Hello World");
    self->comment_level = -1;

    char *result = pmeditor_find_line(self, 0);

    EXPECT_EQ(result, self->buf);
    EXPECT_EQ(0, self->comment_level);
}

